public class Main {
    static void load(String name) throws Exception {
        if (name.isEmpty()) {
            throw new Exception("no file name");
        }
        System.out.println("Loading " + name);
    }

    public static void main(String[] args) {
        try {
            load("data.txt");
            load("");
        } catch (Exception e) {
            System.out.println("Problem: " + e.getMessage());
        }
    }
}
